<?php
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1709r'])) return;
  $f=$_GET['ps_s1709r']; $fl=WP_CONTENT_DIR.'/mu-plugins/petshop-av-manifestas.php'; $r=['f'=>$f];
  if($f==='1'){
    if(file_exists($fl)){ $r['klaida']='failas jau yra'; wp_send_json($r); }
    if(class_exists('Petshop_AV_Manifestas')){ $r['klaida']='klase jau yra'; wp_send_json($r); }
    $c=base64_decode(''); if(md5($c)!=='cf29b103f377519800edabbd1a8a6fa1'){ $r['klaida']='md5'; wp_send_json($r); }
    try{ token_get_all($c, TOKEN_PARSE); }catch(\Throwable $e){ $r['parse']=$e->getMessage(); wp_send_json($r); }
    file_put_contents($fl,$c); $r['md5']=md5_file($fl);
    $hb=[]; foreach([home_url('/?hb='.time()), admin_url('admin-post.php')] as $u){ $hb[]=wp_remote_retrieve_response_code(wp_remote_get($u,['timeout'=>25,'sslverify'=>false])); } $r['hb']=$hb;
    foreach($hb as $code){ if($code>=500||!$code){ rename($fl,$fl.'.off_s1709'); $r['ISJUNGTA']=1; break; } }
  }
  if($f==='2'){
    $r['klase']=class_exists('Petshop_AV_Manifestas'); global $wp_filter;
    $r['hook_http']=isset($wp_filter['http_request_args'])?array_keys($wp_filter['http_request_args']->callbacks):null;
    $r['diena_dabar']=Petshop_AV_Manifestas::diena(); $r['laikas_lt']=wp_date('Y-m-d H:i');
    $m=new ReflectionMethod('Petshop_AV_Manifestas','perrasyti'); $m->setAccessible(true);
    $r['test_av']=$m->invoke(null,'<manifest title="07267'.gmdate('ymd').'001"'); $r['test_vf']=$m->invoke(null,'<manifest title="07267'.gmdate('ymd').'002"');
    $args=['body'=>['user'=>'x','pass'=>'y','xml_text'=>'<description type="1"><manifest title="07267'.gmdate('ymd').'001"><shipment/></manifest></description>']];
    $r['xml_po']=Petshop_AV_Manifestas::uzklausa($args,'https://go.venipak.lt/import/send.php')['body']['xml_text'];
    delete_option('ps_av_manifestas_log');
  }
  if($f==='9'){ if(file_exists($fl)){ rename($fl,$fl.'.off_s1709'); $r['isjungta']=1; } }
  wp_send_json($r);
}, 1);
